INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(54111, 'Joshua 6:5', 'Joshua', 6, 5, 'بیا دې هغوی په لوړ اواز سره سرني ووهي. څنګه چې تاسو هغه واورئ، ټول خلک دې په لوړ اواز چیغې ووهي، نو د ښار دېوالونه به راپرېوځي. بیا به ټول لښکر مخامخ ښار ته ننوځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_5.mp3', '', 1761754199, 1761754199),
(54112, 'Joshua 6:6', 'Joshua', 6, 6, 'یوشع کاهنان راوغوښتل او هغوی ته یې وویل: «د لوظ صندوق واخلئ او اووه تنه د سرنیو سره د هغه په مخکې حرکت وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_6.mp3', '', 1761754199, 1761754199),
(54113, 'Joshua 6:7', 'Joshua', 6, 7, 'بیا هغه قوم ته حکم وکړ: «د ښار څخه ګردچاپېره وګرځئ او وسله وال ساتونکي دې د څښتن د لوظ د صندوق په مخکې روان وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_7.mp3', '', 1761754199, 1761754199),
(54114, 'Joshua 6:8', 'Joshua', 6, 8, 'څنګه چې یوشع قوم ته وینا وکړه، هغه اووه کاهنان چې سرني یې وړل هغوی مخکې روان شول، خپل سرني یې وهل او د څښتن د لوظ صندوق د هغوی پسې ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_8.mp3', '', 1761754199, 1761754199),
(54115, 'Joshua 6:9', 'Joshua', 6, 9, 'وسله وال ساتونکي د هغو کاهنانو په مخکې چې سرني یې وهل روان وو او شاتنۍ ساتونکې ډله د صندوق پسې روانه وه. په دې ټول وخت کې سرني وهل کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_9.mp3', '', 1761754199, 1761754199),
(54116, 'Joshua 6:10', 'Joshua', 6, 10, 'خو یوشع په قوم باندې امر وکړ: «چیغې مه وهئ، ترڅو پورې چې زه تاسو ته امر ونه کړم تاسو به هېڅ نه وایئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_10.mp3', '', 1761754199, 1761754199),
(54117, 'Joshua 6:11', 'Joshua', 6, 11, 'نو یوشع وویل چې د څښتن د لوظ صندوق دې یوځل د ښار څخه ګردچاپېره وګرځوي. بیا ټول خلک بېرته کمپ ته راغلل او هلته یې شپه تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_11.mp3', '', 1761754199, 1761754199),
(54118, 'Joshua 6:12', 'Joshua', 6, 12, 'یوشع سهار وختي پاڅېده او کاهنانو او خپلو کسانو ته یې هماغه امر وکړ. نو هغو کاهنانو چې د لوظ د صندوق د وړلو حکم ورته شوی ؤ هغه په خپلو اوږو باندې کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_12.mp3', '', 1761754199, 1761754199),
(54119, 'Joshua 6:13', 'Joshua', 6, 13, 'بیا هغوی لکه د تېرې ورځې په شان په هماغه ترتیب سره د ښار ګردچاپېره وګرځېدل. لومړی هغه ساتونکي چې مخکې روان وو، بیا هغه کاهنان چې د ګرځېدلو په حال کې به یې هر وخت سرني وهل، ورپسې هغه کاهنان چې د څښتن د لوظ صندوق یې وړلو او په اخره کې شاتنۍ ساتونکې ډله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_13.mp3', '', 1761754199, 1761754199),
(54120, 'Joshua 6:14', 'Joshua', 6, 14, 'نو په دوهمه ورځ هغوی بیا یوځل د ښار څخه ګردچاپېره وګرځېدل او وروسته کمپ ته راستانه شول. هغوی شپږ ورځې دا کار وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_14.mp3', '', 1761754199, 1761754199),
(54121, 'Joshua 6:15', 'Joshua', 6, 15, 'په اوومه ورځ هغوی سهار وختي پاڅېدل او په همدې ډول اووه ځلې د ښار څخه ګردچاپېره وګرځېدل. دا یوازېنۍ ورځ وه چې هغوی اووه ځلې داسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_15.mp3', '', 1761754199, 1761754199),
(54122, 'Joshua 6:16', 'Joshua', 6, 16, 'په اووم ځل کله چې کاهنانو سرني ووهل، یوشع په قوم باندې امر وکړ: «چیغې ووهئ! ځکه چې څښتن دا ښار تاسو ته درکړی دی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_16.mp3', '', 1761754199, 1761754199),
(54123, 'Joshua 6:17', 'Joshua', 6, 17, 'دا ښار او هرڅه چې په کې دي هغه باید څښتن ته د نذرانې په توګه بیخي له منځه یووړل شي. یوازې راحاب بدلمنه او د هغې کورنۍ دې ژوندي پاتې شي، ځکه چې هغې زمونږ جاسوسان پټ کړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_17.mp3', '', 1761754199, 1761754199),
(54124, 'Joshua 6:18', 'Joshua', 6, 18, 'خو تاسو باید هېڅ شی چې له منځه وړل کیږي وانخلئ، که تاسو یې واخلئ، نو د اسراییلو په کمپ باندې به مصیبت او تباهي راولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_18.mp3', '', 1761754199, 1761754199),
(54125, 'Joshua 6:19', 'Joshua', 6, 19, 'ټول سپین زر او سره زر او د برنجو او اوسپنې شیان په ځانګړې توګه د څښتن دي او د هغه په خزانه کې باید کېښودل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_19.mp3', '', 1761754199, 1761754199),
(54126, 'Joshua 6:20', 'Joshua', 6, 20, 'نو کاهنانو سرني ووهل. څنګه چې قوم د سرنیو غږ واورېده، هغوی په لوړ اواز چیغې ووهلې او ناڅاپه د اریحا د ښار دېوالونه راولوېدل. نو بیا ټول لښکر نېغ په نېغه غونډۍ ته وروخوت. هغوی ښار ته ننوتل او هغه یې ونیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_20.mp3', '', 1761754199, 1761754199),
(54127, 'Joshua 6:21', 'Joshua', 6, 21, 'هغوی په خپلو تورو باندې په ښار کې ټول خلک یعنې سړي، ښځې، ځوان او زوړ ټول ووژل. همدارنګه هغوی غویان، پسونه او خره هم ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_21.mp3', '', 1761754199, 1761754199),
(54128, 'Joshua 6:22', 'Joshua', 6, 22, 'نو بیا یوشع هغو دوو کسانو ته چې جاسوسي یې کړې وه وویل: «تاسو د هغې بدلمنې کور ته ورننوځئ او لکه څنګه چې مو د هغې سره وعده کړې وه، هغه او د هغې کورنۍ راوباسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_22.mp3', '', 1761754199, 1761754199),
(54129, 'Joshua 6:23', 'Joshua', 6, 23, 'نو هغوی لاړل او راحاب یې د هغې د مور او پلار، ورونو او د هغې د ټولې کورنۍ سره راوویستل. هغوی د راحاب ټوله کورنۍ یو خوندي ځای ته چې د اسراییلو کمپ ته نژدې ؤ یووړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_23.mp3', '', 1761754199, 1761754199),
(54130, 'Joshua 6:24', 'Joshua', 6, 24, 'بیا د اسراییلو لښکرو ټول ښار د هرڅه سره وسوځاوه، خو هغوی سپین زر او سره زر او د برنجو او اوسپنې شیان د څښتن د کور په خزانه کې کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_24.mp3', '', 1761754199, 1761754199),
(54131, 'Joshua 6:25', 'Joshua', 6, 25, 'خو یوشع د راحاب بدلمنې او د هغې د کورنۍ او ټولو خپلوانو ژوند وژغوره، ځکه چې هغې هغه جاسوسان پټ کړي وو چې یوشع اریحا ته لېږلي وو. (د هغې اولاده تر نن ورځې پورې په اسراییلو کې اوسیږي.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_25.mp3', '', 1761754199, 1761754199),
(54132, 'Joshua 6:26', 'Joshua', 6, 26, 'کله چې اریحا ورانه شوه، نو یوشع په کلکه خبرداری ورکړ: «هرڅوک چې د اریحا د ښار د بیا ودانولو هڅه وکړي، څښتن به په هغه باندې لعنت ووایي: هرڅوک چې کېږدي بنیاد د هغه نو له لاسه وربه کړي خپل مشر زوی هرڅوک چې جوړې کړي د هغه دروازې نو له لاسه وربه کړي خپل کشر زوی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_26.mp3', '', 1761754199, 1761754199),
(54133, 'Joshua 6:27', 'Joshua', 6, 27, 'نو څښتن د یوشع سره مل ؤ او د هغه شهرت په ټول هېواد کې خپور شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua6_verse_27.mp3', '', 1761754199, 1761754199),
(54134, 'Psalms 58:1', 'Psalms', 58, 1, 'تاسو مشران کله کوئ په عدالت پرېکړه؟ ایا قضاوت په انصاف باندې کړئ هرچا سره؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_1.mp3', '', 1761754199, 1761754199),
(54135, 'Psalms 58:2', 'Psalms', 58, 2, 'تاسو همېش جوړوئ خپل زړونو کې بد پلانونه د تاوتریخوالي ډک جرمونه په دنیا کې کوئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_2.mp3', '', 1761754199, 1761754199),
(54136, 'Psalms 58:3', 'Psalms', 58, 3, 'بدکاران وي د مور د ګېډې نه بې‌لارې پیدا چې پیدا شوي دي هغوی له هغې ورځې نه دروغ وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_3.mp3', '', 1761754199, 1761754199),
(54137, 'Psalms 58:4', 'Psalms', 58, 4, 'هغوی له زهرو څخه ډک دي د مارانو په شان د چمچه مار په شان بند کړي یې دي خپل غوږونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_4.mp3', '', 1761754199, 1761754199),
(54138, 'Psalms 58:5', 'Psalms', 58, 5, 'کوم چې نه اوري اواز د پاړوګرو نه منتر د ښو ماهرو پاړوګرو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_5.mp3', '', 1761754199, 1761754199),
(54139, 'Psalms 58:6', 'Psalms', 58, 6, 'د دې ځوانانو زمرو مات کړه ته غاښونه خدایه وڅیره داړې د دوی ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_6.mp3', '', 1761754199, 1761754199),
(54140, 'Psalms 58:7', 'Psalms', 58, 7, 'دوی دې ورکې شي لکه څنګه چې اوبه غیب شي په وچه ځمکه کله چې ولي دوی خپل غشي بې‌اثره دې وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_7.mp3', '', 1761754199, 1761754199),
(54141, 'Psalms 58:8', 'Psalms', 58, 8, 'لکه حلزون په شان دې ویلي شي چکړو کې دوی هغه ماشوم په شان دې شي چې مړ پیدا شي او لمر ونه ګوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_8.mp3', '', 1761754199, 1761754199),
(54142, 'Psalms 58:9', 'Psalms', 58, 9, 'وي د اغزو د اور په څېر او مخکې له دې چې دېګي ستاسې شي ګرم ټول که لامده دي او که وچ، شي به له منځه ولاړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_9.mp3', '', 1761754199, 1761754199),
(54143, 'Psalms 58:10', 'Psalms', 58, 10, 'عادلان به شي خوشحاله چې سزا د ګناهکار وویني د بدکارانو خلکو وینه کې هغوی به خپلې پښې ووینځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_10.mp3', '', 1761754199, 1761754199),
(54144, 'Psalms 58:11', 'Psalms', 58, 11, 'خلک به وایي: «په رښتیا چې نېکان اجر مومي بې له شکه خدای دی چې دنیا باندې کوي قضاوت»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms58_verse_11.mp3', '', 1761754199, 1761754199),
(54145, 'Proverbs 5:1', 'Proverbs', 5, 1, 'ای زما زویه! زما د حکمت خبرو ته پام کوه او د پوهې خبرو ته مې ښه غوږ ونیسه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_1.mp3', '', 1761754199, 1761754199),
(54146, 'Proverbs 5:2', 'Proverbs', 5, 2, 'نو ته به د دې لایق شې چې خپله خوله پټه وساتې او شونډې به دې علم ټینګ وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_2.mp3', '', 1761754199, 1761754199),
(54147, 'Proverbs 5:3', 'Proverbs', 5, 3, 'د بدلمنې ښځې له شونډو نه شات څڅیږي او د خولې خبرې یې د زیتونو له تېلو نه غوړې دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_3.mp3', '', 1761754199, 1761754199),
(54148, 'Proverbs 5:4', 'Proverbs', 5, 4, 'خو په اخر کې د زهرو او زقوم په شان ترخه وي او خوله یې د دوه‌مخې تورې په څېر تېره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_4.mp3', '', 1761754199, 1761754199),
(54149, 'Proverbs 5:5', 'Proverbs', 5, 5, 'د داسې ښځې پښې د مرګ په لور روانې دي او مخامخ د ګور په لور قدمونه اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_5.mp3', '', 1761754199, 1761754199),
(54150, 'Proverbs 5:6', 'Proverbs', 5, 6, 'هېڅکله د ژوند په سمه لار فکر نه کوي او نه پوهیږي چې لارې یې له سرګردانۍ ډکې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_6.mp3', '', 1761754199, 1761754199),
(54151, 'Proverbs 5:7', 'Proverbs', 5, 7, 'نو ای زما زامنو! ماته غوږ ونیسئ څه چې درته وایم، له هغه نه مخ مه اړوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_7.mp3', '', 1761754199, 1761754199),
(54152, 'Proverbs 5:8', 'Proverbs', 5, 8, 'ای زما زویه! له داسې ښځې نه ځان لېرې ساته او د کور دروازې ته یې هم مه ورنژدې کېږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_8.mp3', '', 1761754199, 1761754199),
(54153, 'Proverbs 5:9', 'Proverbs', 5, 9, 'هسې نه چې خپل عزت له لاسه ورکړې او ځواني دې د بې‌رحمه انسان په لاس کې ولویږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_9.mp3', '', 1761754199, 1761754199),
(54154, 'Proverbs 5:10', 'Proverbs', 5, 10, 'او په شتمنۍ دې پردي ماړه شي او د زحمت نتیجه دې د بل چا کور ته لاړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_10.mp3', '', 1761754199, 1761754199),
(54155, 'Proverbs 5:11', 'Proverbs', 5, 11, 'کله چې دې د بدن غوښې له کټ نه وڅڅیږي نو په اخر کې به فریادونه کوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_11.mp3', '', 1761754199, 1761754199),
(54156, 'Proverbs 5:12', 'Proverbs', 5, 12, 'او بیا به افسوس کوې چې «ولې مې نصیحت نه اورېده او څومره به مې زړه اصلاح سپکه ګڼله؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_12.mp3', '', 1761754199, 1761754199),
(54157, 'Proverbs 5:13', 'Proverbs', 5, 13, 'د خپلو ښوونکو خبره به مې نه منله او د خپلو استاذانو خبرو ته به مې غوږ نه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_13.mp3', '', 1761754199, 1761754199),
(54158, 'Proverbs 5:14', 'Proverbs', 5, 14, 'ناڅاپه د بربادۍ کندې ته وغورځېدم او د جرګې او خلکو په مخکې وشرمېدم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_14.mp3', '', 1761754199, 1761754199),
(54159, 'Proverbs 5:15', 'Proverbs', 5, 15, 'یوازې له خپلې ذخیرې نه د مینې اوبه څښه لکه څنګه چې له خپلې څاه نه اوبه څښې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_15.mp3', '', 1761754199, 1761754199),
(54160, 'Proverbs 5:16', 'Proverbs', 5, 16, 'نو دا مناسبه ده چې ستا چینې دې په لارو کې تویې شي او د لښتیو په څېر دې په کوڅو کې روانې وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_16.mp3', '', 1761754199, 1761754199),
(54161, 'Proverbs 5:17', 'Proverbs', 5, 17, 'دا د مینې اوبه دې یوازې ستا وي او له پردیو سره دې شریکې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_17.mp3', '', 1761754199, 1761754199),
(54162, 'Proverbs 5:18', 'Proverbs', 5, 18, 'نو ستا د اوبو په چینه دې برکت شي او د ځوانۍ د وخت له خپلې ښځې نه دې خوند واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_18.mp3', '', 1761754199, 1761754199),
(54163, 'Proverbs 5:19', 'Proverbs', 5, 19, 'هغه یوه مینه ناکه هوسۍ او ښکلې غرڅنۍ ده او د بدن په ښکلا به یې هر وخت موړ شې او د هغې مینه به دې تل سرګردانه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_19.mp3', '', 1761754199, 1761754199),
(54164, 'Proverbs 5:20', 'Proverbs', 5, 20, 'نو ای زما زویه! ولې د بل د ښځې په مینه کې سرګردانه یې او د هغه د ښځې سره یو ځای غاړه په غاړه ویده کېږې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_20.mp3', '', 1761754199, 1761754199),
(54165, 'Proverbs 5:21', 'Proverbs', 5, 21, 'نو د انسان ټولې لارې د څښتن تر نظر لاندې دي او هغه په خپله د انسان ټولې لارې چارې څاري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_21.mp3', '', 1761754199, 1761754199),
(54166, 'Proverbs 5:22', 'Proverbs', 5, 22, 'د بدکاره انسان بدکاري هغه په دام کې نښلوي چې د خپلې ګناه په رسۍ کې به ټینګ ونیول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_22.mp3', '', 1761754199, 1761754199),
(54167, 'Proverbs 5:23', 'Proverbs', 5, 23, 'هغه به د اصلاح له نشتوالي نه مړ شي او د خپل جهالت له ډېروالي نه به سرګردانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs5_verse_23.mp3', '', 1761754199, 1761754199),
(54168, 'Psalms 127:1', 'Psalms', 127, 1, 'ترڅو څښتن جوړ نه کړي کور نو بې‌فایدې به وي د جوړوونکو کار ترڅو څښتن ونه ساتي هغه ښار نو بې‌فایدې به وي ولاړ ورته پهره‌دار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms127_verse_1.mp3', '', 1761754199, 1761754199),
(54169, 'Psalms 127:2', 'Psalms', 127, 2, 'دا بې‌فایدې ده چې سخت کار وکړئ خواړه پیدا کړئ چې شپې ویده شئ تر ناوخته، سهار وختي پاڅېږئ ځکه څښتن ورکوي رزق هغو ته چې مینه کړي ورسره که ویده هم پراته وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms127_verse_2.mp3', '', 1761754199, 1761754199),
(54170, 'Psalms 127:3', 'Psalms', 127, 3, 'اولادونه دي تحفې د څښتن له خوا نه او ماشومان دي اجر د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms127_verse_3.mp3', '', 1761754199, 1761754199),
(54171, 'Psalms 127:4', 'Psalms', 127, 4, 'په ځوانۍ کې چې زامن د چا پیدا شي لکه غشي چې وي لاس کې د عسکر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms127_verse_4.mp3', '', 1761754199, 1761754199),
(54172, 'Psalms 127:5', 'Psalms', 127, 5, 'بختور هغه سړی دی چې وي کڅوړه یې له داسې غشو ډکه ماتې به هېڅکله ونه خوري هغه چې شي دعوه یې له دښمنه سره د جرګې په ځای کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms127_verse_5.mp3', '', 1761754199, 1761754199),
(54173, 'Deuteronomy 18:1', 'Deuteronomy', 18, 1, 'د لاوي د قبیلې کاهنان او د دې قبيلې نور خلک به په اسراييلو کې هېڅ ځمکه تر لاسه نه کړي. د هغې په ځای به هغوی د هغو قربانیو یوه برخه چې څښتن ته وړاندې کیږي، اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_1.mp3', '', 1761754199, 1761754199),
(54174, 'Deuteronomy 18:2', 'Deuteronomy', 18, 2, 'هغوی دې هېڅ ځمکه ونه لري لکه څنګه چې نورې قبیلې یې لري. د څښتن د وعدې سره سم د هغوی برخه دا امتیاز دی چې هغوی د څښتن کاهنان دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_2.mp3', '', 1761754199, 1761754199),
(54175, 'Deuteronomy 18:3', 'Deuteronomy', 18, 3, 'کله چې غویان یا پسونه قرباني کیږي، کاهنانو ته دې اوږه، ژامه او لری ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_3.mp3', '', 1761754199, 1761754199),
(54176, 'Deuteronomy 18:4', 'Deuteronomy', 18, 4, 'هغوی ته دې د غلو دانو، شرابو، د زیتونو د تېلو او د پسونو د وړیو لومړنی حاصل ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_4.mp3', '', 1761754199, 1761754199),
(54177, 'Deuteronomy 18:5', 'Deuteronomy', 18, 5, 'ستاسو څښتن خدای ستاسو د ټولو قبیلو څخه د لاوي قبیله غوره کړه چې د تل دپاره د کاهنانو په توګه د هغه خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_5.mp3', '', 1761754199, 1761754199),
(54178, 'Deuteronomy 18:6', 'Deuteronomy', 18, 6, 'هر لاوي چې زړه یې وغواړي کولای شي د اسراییلو د هر ښار څخه چې په کې اوسیږي هغه ځای ته ورشي چې څښتن یې د خپل عبادت دپاره غوره کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_6.mp3', '', 1761754199, 1761754199),
(54179, 'Deuteronomy 18:7', 'Deuteronomy', 18, 7, 'او کولای شي د نورو ټولو لاویانو په شان چې هلته خدمت کوي هغه هم هلته د خپل څښتن خدای د کاهن په توګه خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_7.mp3', '', 1761754199, 1761754199),
(54180, 'Deuteronomy 18:8', 'Deuteronomy', 18, 8, 'که څه هم کېدای شي چې هغه د خپلې کورنۍ د مال د خرڅولو له لارې پیسې تر لاسه کړې وي، خو هغه دې هم د نورو کاهنانو په اندازه خواړه تر لاسه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_8.mp3', '', 1761754199, 1761754199),
(54181, 'Deuteronomy 18:9', 'Deuteronomy', 18, 9, 'کله چې تاسو هغې خاورې ته ورننوځئ چې خپل څښتن خدای یې درکوي، د هغه ځای د قومونو د ناوړه رواجونو څخه پیروي مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_9.mp3', '', 1761754199, 1761754199),
(54182, 'Deuteronomy 18:10', 'Deuteronomy', 18, 10, 'په خپلو قربانګاوو باندې خپل اولادونه په اور کې مه قرباني کوئ او خپل خلک مه پرېږدئ چې فال وګوري یا کوډو پسې وګرځي یا جادو وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_10.mp3', '', 1761754199, 1761754199),
(54183, 'Deuteronomy 18:11', 'Deuteronomy', 18, 11, 'یا تعویذ نه کار واخلي. همدارنګه خلک مه پرېږدئ چې د مړو سره د مشورې کولو کوښښ وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_11.mp3', '', 1761754199, 1761754199),
(54184, 'Deuteronomy 18:12', 'Deuteronomy', 18, 12, 'ستاسو څښتن خدای د هغو خلکو څخه کرکه کوي چې داسې ناوړه کارونه کوي، نو په دې خاطر څښتن هغه قومونه ستاسو د مخې څخه لېرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_12.mp3', '', 1761754199, 1761754199),
(54185, 'Deuteronomy 18:13', 'Deuteronomy', 18, 13, 'څښتن ته پوره وفادار اوسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_13.mp3', '', 1761754199, 1761754199),
(54186, 'Deuteronomy 18:14', 'Deuteronomy', 18, 14, 'بیا موسی وویل: «په هغه خاوره کې چې تاسو به یې زر ونیسئ، خلک د هغه چا د مشورې څخه پیروي کوي چې کوډې کوي او فال ګوري. خو تاسو ته خپل څښتن خدای اجازه نه درکوي چې داسې کار وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_14.mp3', '', 1761754199, 1761754199),
(54187, 'Deuteronomy 18:15', 'Deuteronomy', 18, 15, 'د دې په ځای به هغه تاسو ته ستاسو د قوم څخه زما په شان یو نبي درولېږي او تاسو باید د هغه اطاعت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_15.mp3', '', 1761754199, 1761754199),
(54188, 'Deuteronomy 18:16', 'Deuteronomy', 18, 16, 'په هغه ورځ چې تاسو د سینا د غره سره راټول شوئ، نو ومو ویل چې مونږ نور نه غواړو د خپل څښتن خدای اواز واورو او دا وېروونکی اور ووینو، ځکه مونږ وېرېږو چې مړه به شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_16.mp3', '', 1761754199, 1761754199),
(54189, 'Deuteronomy 18:17', 'Deuteronomy', 18, 17, 'نو څښتن ماته وویل: ‹هغوی رښتیا وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_17.mp3', '', 1761754199, 1761754199),
(54190, 'Deuteronomy 18:18', 'Deuteronomy', 18, 18, 'زه به هغوی ته د هغوی د خپل قوم څخه ستا په شان یو نبي ورولېږم. زه به ورته ووایم چې څه باید ووایي او هغه به قوم ته هغه څه وایي چې زه یې حکم کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_18.mp3', '', 1761754199, 1761754199),
(54191, 'Deuteronomy 18:19', 'Deuteronomy', 18, 19, 'هغه به زما په نوم خلکو ته خبرې کوي او زه به هر هغه چاته سزا ورکړم چې هغه ته د اطاعت کولو څخه انکار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_19.mp3', '', 1761754199, 1761754199),
(54192, 'Deuteronomy 18:20', 'Deuteronomy', 18, 20, 'خو که چېرې یو نبي جرات وکړي او په داسې وخت کې زما په نوم یو پیغام واوروي چې ما ورته حکم نه وي کړی، نو هغه باید مړ شي او هغه نبي هم باید مړ شي چې د نورو خدایانو په نوم خبرې کوي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_20.mp3', '', 1761754199, 1761754199),
(54193, 'Deuteronomy 18:21', 'Deuteronomy', 18, 21, 'کېدای شي چې ستاسو سره دا سوال پیدا شي چې مونږ څنګه پوهېدلی شو چې د نبي پیغام د څښتن له خوا څخه نه دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_21.mp3', '', 1761754199, 1761754199),
(54194, 'Deuteronomy 18:22', 'Deuteronomy', 18, 22, 'که چېرې یو نبي د څښتن په نوم خبرې وکړي او د هغه خبرې رښتیا نه شي، بیا هغه د څښتن پیغام نه دی. هغه نبي د خپله ځانه دا خبرې کړې دي، نو باید د هغه څخه ونه وېرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy18_verse_22.mp3', '', 1761754199, 1761754199),
(54195, 'Psalms 110:1', 'Psalms', 110, 1, 'څښتن وویل زما بادار ته: «کښېنه زما ښي لاس ته ترڅو چې ستا دښمنان ستا د پښو لاندې کړم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_1.mp3', '', 1761754199, 1761754199),
(54196, 'Psalms 110:2', 'Psalms', 110, 2, 'ستا پاچاهي به کړي پراخه له صهیونه څښتن ته به حکومت کوې په خپلو دښمنانو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_2.mp3', '', 1761754199, 1761754199),
(54197, 'Psalms 110:3', 'Psalms', 110, 3, 'په هغه ورځ چې کوې جنګ له دښمنانو سره په خپله خوښه به ستا خلک راشي سهار وختي لکه د پرخې په شان ستا ځوانان به تاته راشي سپېڅلو غرو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_3.mp3', '', 1761754199, 1761754199),
(54198, 'Psalms 110:4', 'Psalms', 110, 4, 'څښتن قسم خوړلی مات به نه شي هېڅ وخت چې تر ابده به ته یې کاهن د ملک‌صدق د کاهنۍ په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_4.mp3', '', 1761754199, 1761754199),
(54199, 'Psalms 110:5', 'Psalms', 110, 5, 'څښتن ولاړ دی ستا ښي لاس ته کله چې شي هغه په قهر نو پاچاهان به کړي مات', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_5.mp3', '', 1761754199, 1761754199),
(54200, 'Psalms 110:6', 'Psalms', 110, 6, 'محاکمه به کړي قومونه هغه او د جنګ میدان به کړي له مړو نه ډک هغه به ورکړي ماتې د دنیا ټولو پاچاهانو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_6.mp3', '', 1761754199, 1761754199),
(54201, 'Psalms 110:7', 'Psalms', 110, 7, 'هغه به وڅښي اوبه هغې ویالې نه چې په لاره کې ده شي به قوي، هغه کامیاب به ګرځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms110_verse_7.mp3', '', 1761754199, 1761754199),
(54202, 'Exodus 33:1', 'Exodus', 33, 1, 'بیا څښتن موسی ته وویل: «ته او دا قوم چې د مصر څخه دې راوویست، له دې ځای څخه لاړ شئ او هغې ځمکې ته ورشئ چې ما وعده کړې وه چې هغه به ابراهیم، اسحاق، یعقوب او د هغوی اولادې ته ورکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_1.mp3', '', 1761754199, 1761754199),
(54203, 'Exodus 33:2', 'Exodus', 33, 2, 'زه به ستاسو څخه مخکې یوه فرښته ولېږم او کنعانیان، اموریان، حیتیان، فرزیان، حویان او یبوسیان به له هغه ځای څخه راوباسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_2.mp3', '', 1761754199, 1761754199),
(54204, 'Exodus 33:3', 'Exodus', 33, 3, 'تاسو ډېرې غني او حاصلخېزې ځمکې ته ځئ! خو زه به تاسو سره لاړ نه شم، ځکه چې تاسو سرزوری قوم یئ او کېدای شي چې په لاره کې مو له منځه یوسم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_3.mp3', '', 1761754199, 1761754199),
(54205, 'Exodus 33:6', 'Exodus', 33, 6, 'کله چې هغوی د سینا د غره څخه لاړل، نور یې د ګاڼو اچول بس کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_6.mp3', '', 1761754199, 1761754199),
(54206, 'Exodus 33:7', 'Exodus', 33, 7, 'موسی به د کمپ څخه دباندې په یوې لېرې فاصله کې یوه خېمه ودروله او هغه به یې د څښتن د حضورۍ د خېمې په نوم یادوله. هرچا چې به غوښتل د کوم شي په اړه د څښتن رضا معلومه کړي، نو هغې خېمې ته به ورتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_7.mp3', '', 1761754199, 1761754199),
(54207, 'Exodus 33:8', 'Exodus', 33, 8, 'کله به چې موسی هغې خېمې ته ورتله، ټول خلک به د خپلو خېمو په دروازو کې ودرېدل او موسی ته به یې تر هغه وخته پورې کتل، ترڅو چې به هغه خېمې ته ورننوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_8.mp3', '', 1761754199, 1761754199),
(54208, 'Exodus 33:9', 'Exodus', 33, 9, 'د موسی د ننوتلو څخه وروسته به هغه د ستنې په شان ورېځ راښکته کېدله او د خېمې د دروازې په خولې کې به ودرېدله او څښتن به د موسی سره د هغې ورېځې له منځ نه خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_9.mp3', '', 1761754199, 1761754199),
(54209, 'Exodus 33:10', 'Exodus', 33, 10, 'څنګه به چې قوم د خېمې په دروازه کې هغه ورېځ لیدله چې ولاړه به وه، نو ټول به په سجده پرېوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_10.mp3', '', 1761754199, 1761754199),
(54210, 'Exodus 33:11', 'Exodus', 33, 11, 'څښتن به موسی سره مخامخ خبرې کولې لکه څنګه چې یو سړی د خپل ملګري سره خبرې کوي. بیا به موسی کمپ ته راستنېده، خو د هغه ځوان مرستیال د نون زوی یوشع به په خېمه کې پاتې کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus33_verse_11.mp3', '', 1761754199, 1761754199);